-- 0167: Sailor Moon — Kakeru Ōzora (Film „Sailor Moon S“) ist Astronom, kein Astronaut. Idempotent.
update question_translations set options = jsonb_set(options, '{1}', to_jsonb('An astronomer'::text)) where lang = 'en' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'In wen verliebt sich die Katze Luna im Kinofilm „Sailor Moon S“?');
